function confirmDialog(title,message,buttonText,action,context=""){state.confirmAction=action;$("#confirmTitle").textContent=title;$("#confirmMessage").textContent=message;$("#confirmProceed").textContent=buttonText;$("#confirmContext").textContent=context;$("#confirmContext").classList.toggle("hidden",!context);$("#confirmDialog").classList.remove("hidden");$("#confirmCancel").focus();}
function closeConfirm(){state.confirmAction=null;$("#confirmDialog").classList.add("hidden");}
async function submitAction(key,url,body,success,openRun=false){if(state.pending.has(key))return;state.pending.add(key);state.actionErrors.delete(key);renderAccounts();try{const result=await api(url,{method:"POST",body:JSON.stringify(body)});toast(success);await loadOverview(true);if(openRun&&result?.run_id)openDrawer("run",result.run_id);}catch(e){state.actionErrors.set(key,e.message);toast("操作失败",e.message,"error");}finally{state.pending.delete(key);renderAccounts();if(state.drawer==="account")renderAccountDrawer(state.drawerId,true);}}
function accountById(id){return state.accounts.find(a=>String(a.id)===String(id));}
function eligibleOnResume(){return state.accounts.filter(a=>{const c=capability(a,"auto_schedule"),reason=c.block_reason;return a.auto_schedule_enabled&&!a.current_run&&(!reason||["global_schedule_paused","retry_cooldown"].includes(reason));}).length;}
function retryEligible(){return state.runs.filter(r=>r.retry_eligible&&!r.retry_of_run_id).length;}
function handleAction(button){if(button.disabled)return;const action=button.dataset.action,id=button.dataset.id,a=accountById(id);if(action==="account-drawer")return openDrawer("account",id,button);if(action==="run-drawer")return openDrawer("run",button.dataset.runId,button);if(action==="start"){button.closest("details")?.removeAttribute("open");const d=button.dataset.duration;return submitAction(actionKey(id,`start-${d}`),`/api/x/accounts/${encodeURIComponent(id)}/start`,{duration_minutes:d==="remaining"?"remaining":number(d)},"浏览任务已提交",true);}if(action==="probe")return submitAction(actionKey(id,"probe"),`/api/x/accounts/${encodeURIComponent(id)}/probe`,{},"状态检测已提交",true);if(action==="pause-schedule"||action==="resume-schedule")return submitAction(actionKey(id,action),`/api/x/accounts/${encodeURIComponent(id)}/${action}`,{},action==="pause-schedule"?"账号排程已暂停":"账号排程已恢复");if(action==="cancel-current")return confirmDialog("停止当前任务？",`${a?.persona_label||"该账号"}会在安全检查点停止；已使用预算不会回退。`,"确认停止",()=>submitAction(actionKey(id,"cancel"),`/api/x/accounts/${encodeURIComponent(id)}/cancel-current`,{},"已请求停止"));if(action==="cleanup"||action==="reconcile"){const job=button.dataset.jobId,label=action==="cleanup"?"请求清理":"重新对账";return confirmDialog(`${label}？`,`Job ${job} 将记录一条审计操作并由 Worker 安全处理。`,label,()=>submitAction(actionKey(id,action),`/api/x/jobs/${encodeURIComponent(job)}/${action}`,{},`${label}已提交`));}}
const writeState={status:null,oauth:null,accounts:[],requests:[],operations:[],audit:[],credentialRefs:[],secretsConfigured:false,unavailable:"",draft:null,activeFlow:null,loading:false,form:{account_id:"",request_type:"like",target:"",text:"",title:"",body:""},connect:{source_profile_id:"",account_id:"",display_name:""}};
const WRITE_TYPES=[["like","点赞"],["unlike","取消点赞"],["repost","转发"],["unrepost","取消转发"],["post_create","发布帖子"],["post_delete","删除帖子"],["article_draft_publish","发布 X 文章"]];
function writeTone(s){const k=String(s||"");if(["succeeded","reconciled_succeeded"].includes(k))return"ok";if(["failed","failed_known","uncertain","manual_reconciliation_required"].includes(k))return"bad";if(["queued","executing","running"].includes(k))return"info";return"warn";}
function writeAccountName(id){const a=writeState.accounts.find(x=>x.id===id);return a?`${a.display_name||a.account_key}${a.x_user_id?` · ${a.x_user_id}`:""}`:`账号 ${id}`;}
function writeTargetSummary(r){const p=r.payload||{};if(p.target)return`目标帖子 ${p.target}`;if(p.text)return`“${p.text.length>70?p.text.slice(0,70)+"…":p.text}”`;if(p.article)return`《${p.article.title}》 · ${list(p.article.blocks).length} 个内容区块`;return"";}
function secureConsole(){return location.protocol==="https:"||["localhost","127.0.0.1"].includes(location.hostname);}
function safeOAuthUrl(value){try{const u=new URL(value);return u.protocol==="https:"&&["twitter.com","x.com"].some(h=>u.hostname===h||u.hostname.endsWith(`.${h}`))&&!u.username&&!u.password?u.href:null;}catch{return null;}}
function browseProfile(id){return state.accounts.find(a=>String(a.profile_id)===String(id));}
function writeCredential(a){const ref=a.credential_ref||a.account_key;return writeState.credentialRefs.find(r=>r.ref===ref)||null;}
function writeCapability(a,type){const caps=a?.capabilities||{},name=type==="article_draft_publish"?"article_draft":type,c=caps[name];if(!c||typeof c!=="object")return{allowed:a?.authorization_status==="verified"&&type!=="article_draft_publish",reason:type==="article_draft_publish"?"article_entitlement_unverified":a?.authorization_status==="verified"?null:"identity_unverified"};return{allowed:Boolean(c.allowed),reason:c.reason||null};}
function profileLabel(a){return`${a.persona_label||a.serial_number||a.profile_id} · Profile ${a.profile_id}${a.observed_handle||a.expected_handle?` · ${handle(a.observed_handle||a.expected_handle)}`:""}`;}
async function loadWrite(silent=false){if(writeState.loading||state.view!=="write")return;writeState.loading=true;try{const[s,a,r,o,u,c,x]=await Promise.all([api("/api/x-write/status"),api("/api/x-write/accounts"),api("/api/x-write/requests?limit=50"),api("/api/x-write/operations?limit=50"),api("/api/x-write/audit?limit=30"),api("/api/x-write/credential-refs"),api("/api/x-write/oauth/status")]);writeState.status=s;writeState.oauth=x;writeState.accounts=list(a.accounts);writeState.requests=list(r.requests);writeState.operations=list(o.operations);writeState.audit=list(u.audit);writeState.credentialRefs=list(c.credential_refs);writeState.secretsConfigured=Boolean(c.secrets_configured);if(writeState.activeFlow?.flow_key){const flow=await api(`/api/x-write/oauth/flows/${encodeURIComponent(writeState.activeFlow.flow_key)}`);writeState.activeFlow={...writeState.activeFlow,...flow};if(["succeeded","failed","expired","cancelled"].includes(flow.status)&&!writeState.activeFlow.notified){writeState.activeFlow.notified=true;toast(flow.status==="succeeded"?"X 账号授权已接收":"X 账号授权未完成",flow.status==="succeeded"?"账号仍保持停用和暂停，请继续核对身份。":textStatus(flow.error_code||flow.status),flow.status==="succeeded"?"success":"error");}}writeState.unavailable="";}catch(e){writeState.unavailable=e.message;if(!silent)toast("写入服务同步失败",e.message,"error");}finally{writeState.loading=false;}renderWrite();}
async function writeAction(key,url,body,success){if(state.pending.has(key))return;state.pending.add(key);try{const result=await api(url,{method:"POST",body:JSON.stringify(body||{})});if(success)toast(success);await loadWrite(true);return result;}catch(e){toast("写入操作失败",e.message,"error");return null;}finally{state.pending.delete(key);}}
function renderWrite(){if(state.view!=="write")return;renderWriteStatus();renderWriteOAuth();renderWriteNew();renderWritePending();renderWriteOperations();renderWriteAccounts();renderWriteAudit();}
function renderWriteStatus(){const el=$("#writeStatusPanel");if(writeState.unavailable){el.innerHTML=`<div class="page-alert">写入服务不可用：${esc(writeState.unavailable)}。浏览功能不受影响；配置 X Console 的写入服务地址和内部密钥后可用。</div>`;return;}const s=writeState.status||{},paused=s.global_write_paused!==false,uncertain=number(s.uncertain_operations);el.innerHTML=`<div class="write-banner ${paused?"paused":""}"><div class="status-item"><span class="state-mark ${paused?"warn":"ok"}"></span><span><b>官方 API 写入服务：${paused?"已暂停":"可用"}</b><small>与浏览排程互不影响；逐项人工确认后才会发送</small></span></div><div class="write-banner-facts"><span>待批准 ${number((s.requests_by_status||{}).pending_approval)}</span><span>排队 ${number((s.operations_by_status||{}).queued)}</span><span>结果不确定 ${uncertain}</span><span>写入账号 ${number(s.accounts_total)}</span></div><button class="button ${paused?"primary":"secondary"}" data-write-action="${paused?"write-resume":"write-pause"}" type="button">${paused?"恢复写入服务":"暂停写入服务"}</button></div>${s.executor_last_error?`<div class="page-alert">执行器最近错误：${esc(textStatus(s.executor_last_error))}</div>`:""}`;}
function renderWriteOAuth(){const el=$("#writeOAuthPanel");if(writeState.unavailable){el.innerHTML="";return;}const o=writeState.oauth||{},app=o.developer_app||{},secure=secureConsole(),callback=String(o.callback_url||""),profiles=state.accounts.filter(a=>!writeState.accounts.some(w=>String(w.source_profile_id||"")===String(a.profile_id))),unverified=writeState.accounts.filter(a=>a.authorization_status!=="verified");if(profiles.length&&!profiles.some(a=>String(a.profile_id)===String(writeState.connect.source_profile_id)))writeState.connect.source_profile_id=String(profiles[0].profile_id);if(!unverified.some(a=>String(a.id)===String(writeState.connect.account_id)))writeState.connect.account_id="";const selected=browseProfile(writeState.connect.source_profile_id);if(selected&&!writeState.connect.display_name)writeState.connect.display_name=selected.persona_label||selected.serial_number||`Profile ${selected.profile_id}`;const ready=Boolean(o.oauth2_ready&&secure),flow=writeState.activeFlow,authorization=flow?safeOAuthUrl(flow.authorization_url):null,terminal=flow&&["succeeded","failed","expired","cancelled"].includes(flow.status);const callbackReason=!secure?"当前通过 HTTP 打开，禁止提交任何 Developer Secret。请先使用正式 HTTPS 地址。":!o.callback_configured?"服务器尚未配置固定 HTTPS OAuth 回调地址。":!app.configured?"先配置 X Developer App 的 Client ID / Secret。":"";el.innerHTML=`<div class="oauth-layout"><section class="oauth-card"><h3>1. Developer App</h3><p>只需配置一次。Client ID/Secret 本身不能发帖，还需要每个 X 账号分别授权。</p><dl class="oauth-facts"><dt>HTTPS 页面</dt><dd>${secure?"已满足":"未满足"}</dd><dt>Callback</dt><dd>${esc(callback||"未配置")}</dd><dt>Client ID</dt><dd>${esc(app.client_id_masked||"未配置")}</dd><dt>Client Secret</dt><dd>${app.client_secret_configured?"已安全保存":"未配置"}</dd><dt>授权 scopes</dt><dd>${esc(list(o.required_scopes).join(" · ")||"--")}</dd></dl>${callbackReason?`<div class="disabled-reason">${esc(callbackReason)}</div>`:""}<div class="action-row write-actions"><button class="button secondary" data-write-action="configure-oauth-app" type="button" ${secure&&o.callback_configured?"":"disabled"}>${app.configured?"更新 App 配置":"配置 App"}</button>${callback?`<button class="button secondary" data-write-action="copy-callback" data-copy-value="${esc(callback)}" type="button">复制 Callback</button>`:""}<button class="button secondary" data-write-action="open-oauth1" type="button" ${secure?"":"disabled"}>其他方式：OAuth 1.0a</button></div></section><section class="oauth-card"><h3>2. 在 Windows Profile 中授权</h3><p>控制台只生成一次性链接；请复制到对应账号已登录的 AdsPower Profile 中打开并人工确认。</p><div class="settings-form write-form"><label><span>Windows Profile</span><select data-oauth-connect-field="source_profile_id">${profiles.length?profiles.map(a=>`<option value="${esc(a.profile_id)}" ${String(a.profile_id)===String(writeState.connect.source_profile_id)?"selected":""}>${esc(profileLabel(a))}</option>`).join(""):`<option value="">没有未关联 Profile</option>`}</select></label><label><span>绑定现有写入账号（可选）</span><select data-oauth-connect-field="account_id"><option value="">自动新建</option>${unverified.map(a=>`<option value="${a.id}" ${String(a.id)===String(writeState.connect.account_id)?"selected":""}>${esc(a.display_name||`账号 ${a.id}`)}（待授权）</option>`).join("")}</select></label><label class="full"><span>写入账号显示名称</span><input data-oauth-connect-field="display_name" maxlength="120" value="${esc(writeState.connect.display_name)}"></label></div><div class="oauth-security-note">Windows Worker 不会收到链接、Cookie 或 Token，也不会自动点击授权。账号授权成功后仍保持停用和暂停。</div><div class="action-row write-actions"><button class="button primary" data-write-action="start-oauth" type="button" ${ready&&profiles.length?"":"disabled"}>生成一次性授权链接</button></div>${flow?`<div class="oauth-flow"><strong>${terminal?`授权状态：${esc(textStatus(flow.error_code||flow.status))}`:"一次性授权链接已生成"}</strong><small>目标 ${esc(flow.source_label||flow.source_profile_id||"Windows Profile")} · ${esc(time(flow.expires_at))} 前有效</small>${authorization&&!terminal?`<span class="oauth-flow-url">${esc(authorization)}</span><div class="action-row write-actions"><a class="button secondary" href="${esc(authorization)}" target="_blank" rel="noopener noreferrer">在当前浏览器打开</a><button class="button primary" data-write-action="copy-oauth-link" type="button">复制到 Windows Profile</button><button class="button secondary" data-write-action="cancel-oauth" type="button">作废链接</button></div>`:`<div class="action-row write-actions"><button class="button secondary" data-write-action="clear-oauth-flow" type="button">关闭结果</button></div>`}</div>`:""}</section></div>`;}
function renderWriteNew(){const el=$("#writeNewPanel");if(writeState.unavailable){el.innerHTML="";return;}const f=writeState.form,d=writeState.draft;if(d){const pending=d.status==="pending_approval";el.innerHTML=`<div class="preview-box"><h3>请求预览（已冻结，内容不可再改）</h3><dl class="definition-list"><dt>账号</dt><dd>${esc(writeAccountName(d.account_id))}</dd><dt>动作</dt><dd>${esc(textStatus(d.request_type))}</dd><dt>内容</dt><dd>${esc(writeTargetSummary(d))}</dd><dt>内容指纹</dt><dd title="${esc(d.content_hash)}">${esc(d.content_hash.slice(0,16))}…</dd><dt>版本</dt><dd>v${number(d.version,1)}</dd><dt>状态</dt><dd>${esc(textStatus(d.status))}</dd></dl><div class="action-row">${pending?`<button class="button primary" data-write-action="approve-draft" type="button">批准此精确请求</button>`:`<button class="button primary" data-write-action="submit-draft" type="button">提交审批</button>`}<button class="button secondary" data-write-action="discard-draft" type="button">放弃</button></div></div>`;return;}if(!writeState.accounts.length){el.innerHTML=`<div class="empty-state">先在上方“连接 X 写入账号”完成授权。</div>`;return;}if(!f.account_id||!writeState.accounts.some(a=>String(a.id)===String(f.account_id)))f.account_id=String(writeState.accounts[0].id);const account=writeState.accounts.find(a=>String(a.id)===String(f.account_id)),t=f.request_type,allowed=writeCapability(account,t),ready=account?.authorization_status==="verified"&&allowed.allowed;el.innerHTML=`<div class="settings-form write-form"><label><span>写入账号（单选）</span><select data-write-field="account_id">${writeState.accounts.map(a=>`<option value="${a.id}" ${String(a.id)===String(f.account_id)?"selected":""}>${esc(a.display_name||`账号 ${a.id}`)}${a.metadata?.verified_username?` · @${esc(a.metadata.verified_username)}`:""}${a.paused||!a.enabled?"（未启用）":""}</option>`).join("")}</select></label><label><span>动作</span><select data-write-field="request_type">${WRITE_TYPES.map(([v,l])=>{const c=writeCapability(account,v);return`<option value="${v}" ${v===t?"selected":""} ${c.allowed?"":"disabled"}>${l}${c.allowed?"":`（${esc(textStatus(c.reason))}）`}</option>`;}).join("")}</select></label>${["like","unlike","repost","unrepost","post_delete"].includes(t)?`<label class="full"><span>目标帖子 URL 或 ID</span><input data-write-field="target" value="${esc(f.target)}" placeholder="https://x.com/.../status/123 或 123"></label>`:""}${t==="post_create"?`<label class="full"><span>帖子正文（最多 280 字）</span><textarea data-write-field="text" rows="3" maxlength="280">${esc(f.text)}</textarea></label>`:""}${t==="article_draft_publish"?`<label class="full"><span>文章标题</span><input data-write-field="title" value="${esc(f.title)}" maxlength="250"></label><label class="full"><span>文章正文（创建草稿后仍需第二次确认才会公开发布）</span><textarea data-write-field="body" rows="6">${esc(f.body)}</textarea></label>`:""}</div>${ready?"":`<div class="disabled-reason">当前账号不可创建此请求：${esc(textStatus(allowed.reason||account?.authorization_status||"identity_unverified"))}。</div>`}<div class="action-row write-actions"><button class="button primary" data-write-action="create-draft" type="button" ${ready?"":"disabled"}>创建草稿并预览</button></div>${t==="post_delete"?`<div class="disabled-reason">删除帖子是不可恢复操作，批准后才会执行。</div>`:""}`;}
function renderWritePending(){const pending=writeState.requests.filter(r=>r.status==="pending_approval"&&(!writeState.draft||r.id!==writeState.draft.id)),awaiting=writeState.operations.filter(o=>o.status==="awaiting_approval");$("#writePendingCount").textContent=`${pending.length+awaiting.length} 项`;$("#writePendingList").innerHTML=pending.length+awaiting.length?[...pending.map(r=>`<div class="write-row"><div class="write-row-main"><strong>${esc(textStatus(r.request_type))} · ${esc(writeAccountName(r.account_id))}</strong><small>${esc(writeTargetSummary(r))} · 指纹 ${esc(r.content_hash.slice(0,12))}…</small></div><div class="action-row"><button class="button primary" data-write-action="approve-request" data-request-id="${r.id}" type="button">批准</button><button class="button secondary" data-write-action="cancel-request" data-request-id="${r.id}" type="button">取消</button></div></div>`),...awaiting.map(o=>`<div class="write-row"><div class="write-row-main"><strong>X 文章草稿已创建 · ${esc(writeAccountName(o.account_id))}</strong><small>草稿 ID ${esc(o.external_object_id||"--")} · 需要第二次确认才会公开发布</small></div><div class="action-row"><button class="button danger" data-write-action="approve-next-step" data-operation-id="${o.id}" type="button">确认发布文章</button></div></div>`)].join(""):`<div class="empty-state">当前没有待处理的写入请求。</div>`;}
function renderWriteOperations(){const ops=writeState.operations;$("#writeOperationsCount").textContent=`${ops.length} 条`;$("#writeOperationsList").innerHTML=ops.length?ops.map(o=>`<div class="write-row"><div class="write-row-main"><strong>${esc(textStatus(o.operation_type))} · ${esc(writeAccountName(o.account_id))}</strong><small>${o.external_object_id?`结果 ID ${esc(o.external_object_id)} · `:""}${o.error_code?`${esc(textStatus(o.error_code))}${o.retry_after?` · 可在此时间后重试 ${esc(time(o.retry_after))}`:""} · `:""}${esc(time(o.updated_at))}</small>${o.status==="uncertain"?`<div class="write-reconcile"><input data-write-note-id="${o.id}" placeholder="对账说明（必填，例如：已在 x.com 确认结果）"><div class="action-row"><button class="button secondary" data-write-action="reconcile-succeeded" data-operation-id="${o.id}" type="button">确认已成功</button><button class="button secondary" data-write-action="reconcile-failed" data-operation-id="${o.id}" type="button">确认未成功</button></div><small>不会重新发送，只记录对账结论。</small></div>`:""}${o.reconciliation_note?`<small>对账：${esc(o.reconciliation_note)}（${esc(o.reconciled_by||"")}）</small>`:""}</div><span class="badge ${writeTone(o.status)}">${esc(textStatus(o.status))}</span></div>`).join(""):`<div class="empty-state">还没有写入操作记录。</div>`;}
function renderWriteAccounts(){const listEl=$("#writeAccountsList"),oauthReady=Boolean(writeState.oauth?.oauth2_ready&&secureConsole());$("#writeAccountsCount").textContent=`${writeState.accounts.length} 个账号`;listEl.innerHTML=writeState.accounts.length?writeState.accounts.map(a=>{const credential=writeCredential(a),verified=a.metadata?.verified_at,authorized=a.authorization_status==="verified",authLabel=a.auth_type==="oauth2"?"OAuth 2.0":a.auth_type==="oauth1"?"OAuth 1.0a":"未授权",scopes=list(credential?.scopes),capabilities=Object.values(a.capabilities||{}),allowed=capabilities.filter(c=>c?.allowed).length;return`<div class="write-row"><div class="write-row-main"><strong>${esc(a.display_name||`写入账号 ${a.id}`)}</strong><small>${a.metadata?.verified_username?`@${esc(a.metadata.verified_username)} · `:""}${a.x_user_id?`X ID ${esc(a.x_user_id)}`:"未绑定 X 身份"}${a.source_profile_id?` · Windows Profile ${esc(a.source_profile_id)}`:""}</small><div class="credential-meta"><span class="badge ${authorized?"ok":"warn"}">${esc(authLabel)}</span><span class="badge ${credential?.complete?"ok":"warn"}">${credential?.complete?"凭据可用":"待完成授权"}</span>${credential?.expires_at?`<span class="badge ${number(credential.expires_at)*1000<Date.now()+600000?"warn":"info"}">到期 ${esc(time(credential.expires_at))}</span>`:""}${capabilities.length?`<span class="badge info">能力 ${allowed}/${capabilities.length}</span>`:""}</div>${scopes.length?`<small class="credential-scope">Scopes：${esc(scopes.join(" · "))}</small>`:""}${!authorized?`<small>请在上方选择对应 Windows Profile 生成授权链接；无需填写账号标识。</small>`:""}</div><div class="write-row-side"><span class="badge ${a.enabled&&!a.paused?"ok":"warn"}">${a.enabled?(a.paused?"已暂停":"已启用"):"未启用"}</span><div class="action-row"><button class="button secondary" data-write-action="verify-account" data-write-account-id="${a.id}" type="button" ${credential?.complete?"":"disabled"}>验证身份</button>${a.auth_type==="oauth2"?`<button class="button secondary" data-write-action="reconnect-oauth" data-write-account-id="${a.id}" type="button" ${oauthReady?"":"disabled"}>重新连接</button>`:a.auth_type==="oauth1"?`<button class="button secondary" data-write-action="rotate-oauth1" data-write-account-id="${a.id}" type="button" ${secureConsole()?"":"disabled"}>更换凭据</button>`:""}${a.enabled?`<button class="button secondary" data-write-action="disable-account" data-write-account-id="${a.id}" type="button">停用</button>`:`<button class="button secondary" data-write-action="enable-account" data-write-account-id="${a.id}" type="button" ${authorized?"":"disabled"}>启用</button>`}${a.paused?`<button class="button secondary" data-write-action="resume-account" data-write-account-id="${a.id}" type="button" ${authorized&&a.enabled?"":"disabled"}>恢复</button>`:`<button class="button secondary" data-write-action="pause-account" data-write-account-id="${a.id}" type="button">暂停</button>`}</div></div></div>`;}).join(""):`<div class="empty-state">还没有写入账号。请在上方选择 Windows Profile 并生成一次性授权链接。</div>`;}
function renderWriteAudit(){$("#writeAuditList").innerHTML=writeState.audit.length?writeState.audit.map(row=>`<div class="write-row compact"><div class="write-row-main"><strong>${esc(row.event_type)}</strong><small>${esc(row.actor)} · ${esc(row.target_type)} ${esc(row.target_id||"")} · ${esc(time(row.created_at))}</small></div></div>`).join(""):`<div class="empty-state">暂无审计记录。</div>`;}
function writeFormPayload(){const f=writeState.form,t=f.request_type;if(["like","unlike","repost","unrepost","post_delete"].includes(t))return{target:f.target.trim()};if(t==="post_create")return{text:f.text};return{article:{schema_version:1,title:f.title.trim(),blocks:[{type:"paragraph",text:f.body.trim()}]}};}
async function copyValue(value,label){if(!value)return;try{await navigator.clipboard.writeText(value);toast(`${label}已复制`);}catch{toast("复制失败","请在 HTTPS 页面允许剪贴板权限后重试。","error");}}
function closeSecretDialogs(){for(const id of ["oauthAppDialog","oauth1Dialog"]){const dialog=$(`#${id}`);dialog?.classList.add("hidden");dialog?.querySelector("form")?.reset();}$("#oauthAppError").textContent="";$("#oauth1Error").textContent="";}
function openOAuth1Dialog(accountId=""){const profiles=state.accounts,profileSelect=$("#oauth1ProfileSelect"),accountSelect=$("#oauth1AccountSelect");profileSelect.innerHTML=`<option value="">不关联浏览 Profile</option>${profiles.map(a=>`<option value="${esc(a.profile_id)}">${esc(profileLabel(a))}</option>`).join("")}`;accountSelect.innerHTML=`<option value="">自动新建</option>${writeState.accounts.map(a=>`<option value="${a.id}" ${String(a.id)===String(accountId)?"selected":""}>${esc(a.display_name||`账号 ${a.id}`)}</option>`).join("")}`;const account=writeState.accounts.find(a=>String(a.id)===String(accountId));if(account?.source_profile_id)profileSelect.value=String(account.source_profile_id);const form=$("#oauth1Form");form.elements.display_name.value=account?.display_name||"";$("#oauth1Dialog").classList.remove("hidden");form.elements.consumer_key.focus();}
async function handleWriteAction(el){const action=el.dataset.writeAction,id=el.dataset.requestId||el.dataset.operationId||el.dataset.writeAccountId;if(action==="write-pause"||action==="write-resume"){const resume=action==="write-resume";confirmDialog(resume?"恢复写入服务？":"暂停写入服务？",resume?"恢复后，已批准的写入请求才会继续执行；浏览排程不受影响。":"暂停后立即阻止新的 X API 发送，不影响浏览功能，也不会撤销已完成的写入。",resume?"确认恢复":"确认暂停",()=>writeAction(`write:${action}`,`/api/x-write/global/${resume?"resume":"pause"}`,{},resume?"写入服务已恢复":"写入服务已暂停"));return;}if(action==="configure-oauth-app"){$("#oauthAppForm").reset();$("#oauthAppError").textContent="";$("#oauthAppDialog").classList.remove("hidden");$("#oauthAppForm").elements.client_id.focus();return;}if(action==="open-oauth1"){openOAuth1Dialog();return;}if(action==="rotate-oauth1"){openOAuth1Dialog(id);return;}if(action==="copy-callback"){await copyValue(el.dataset.copyValue,"Callback");return;}if(action==="copy-oauth-link"){await copyValue(writeState.activeFlow?.authorization_url,"授权链接");return;}if(action==="clear-oauth-flow"){writeState.activeFlow=null;renderWriteOAuth();return;}if(action==="cancel-oauth"&&writeState.activeFlow?.flow_key){const flow=writeState.activeFlow;confirmDialog("作废此授权链接？","作废后该链接不能再次使用，不影响任何已连接账号。","确认作废",async()=>{await writeAction(`write:oauth-cancel:${flow.flow_key}`,`/api/x-write/oauth/flows/${encodeURIComponent(flow.flow_key)}/cancel`,{},"授权链接已作废");writeState.activeFlow=null;renderWriteOAuth();});return;}if(action==="start-oauth"||action==="reconnect-oauth"){const account=action==="reconnect-oauth"?writeState.accounts.find(a=>String(a.id)===String(id)):null,profile=browseProfile(account?.source_profile_id||writeState.connect.source_profile_id);if(!profile){toast("请选择对应的 Windows Profile","","error");return;}const payload={source_profile_id:String(profile.profile_id),source_label:profileLabel(profile),display_name:(account?.display_name||writeState.connect.display_name||profile.persona_label||"").trim(),...(account?{account_id:account.id}:writeState.connect.account_id?{account_id:number(writeState.connect.account_id)}:{})};const result=await writeAction(`write:oauth-start:${account?.id||profile.profile_id}`,"/api/x-write/oauth/start",payload,"一次性授权链接已生成");if(result){writeState.activeFlow=result;renderWriteOAuth();}return;}
if(action==="create-draft"){const account=writeState.accounts.find(a=>String(a.id)===String(writeState.form.account_id)),cap=writeCapability(account,writeState.form.request_type);if(!account||account.authorization_status!=="verified"||!cap.allowed){toast("当前账号或动作尚不可用",textStatus(cap.reason||account?.authorization_status||"identity_unverified"),"error");return;}const f=writeState.form;if(!f.account_id){toast("请选择写入账号","","error");return;}const result=await writeAction("write:create","/api/x-write/requests",{account_id:number(f.account_id),request_type:f.request_type,payload:writeFormPayload()});if(result){writeState.draft=result;renderWrite();}return;}
if(action==="submit-draft"&&writeState.draft){const result=await writeAction("write:submit",`/api/x-write/requests/${writeState.draft.id}/submit`,{});if(result){writeState.draft=result;renderWrite();}return;}
if(action==="approve-draft"&&writeState.draft){const d=writeState.draft;confirmDialog("批准此精确请求？",`${textStatus(d.request_type)} · ${writeAccountName(d.account_id)} · ${writeTargetSummary(d)}`,"确认批准",async()=>{const result=await writeAction("write:approve",`/api/x-write/requests/${d.id}/approve`,{content_hash:d.content_hash,request_version:d.version});if(result)writeState.draft=null;},"批准后请求进入执行队列；发送结果不确定时不会自动重试。");return;}
if(action==="discard-draft"&&writeState.draft){const d=writeState.draft;await writeAction("write:discard",`/api/x-write/requests/${d.id}/cancel`,{},"已放弃该请求");writeState.draft=null;renderWrite();return;}
if(action==="approve-request"||action==="cancel-request"){const r=writeState.requests.find(x=>String(x.id)===String(id));if(!r)return;if(action==="cancel-request"){await writeAction(`write:cancel:${id}`,`/api/x-write/requests/${id}/cancel`,{},"请求已取消");return;}confirmDialog("批准此精确请求？",`${textStatus(r.request_type)} · ${writeAccountName(r.account_id)} · ${writeTargetSummary(r)}`,"确认批准",()=>writeAction(`write:approve:${id}`,`/api/x-write/requests/${id}/approve`,{content_hash:r.content_hash,request_version:r.version},"已批准，进入执行队列"),"批准后请求进入执行队列；发送结果不确定时不会自动重试。");return;}
if(action==="approve-next-step"){const detail=await api(`/api/x-write/operations/${id}`).catch(e=>(toast("读取操作详情失败",e.message,"error"),null));if(!detail||!detail.request)return;confirmDialog("确认公开发布 X 文章？",`文章草稿 ${detail.external_object_id||"--"} · ${writeAccountName(detail.account_id)} · 《${detail.request.payload?.article?.title||"--"}》`,"确认发布",()=>writeAction(`write:next:${id}`,`/api/x-write/operations/${id}/approve-next-step`,{content_hash:detail.request.content_hash},"已确认，发布将继续执行"),"发布后不可撤销；此确认仅授权发布步骤。");return;}
if(action==="reconcile-succeeded"||action==="reconcile-failed"){const note=$(`[data-write-note-id="${id}"]`)?.value||"",outcome=action==="reconcile-succeeded"?"succeeded":"failed";if(!note.trim()){toast("请填写对账说明","","error");return;}confirmDialog(outcome==="succeeded"?"确认该操作已成功？":"确认该操作未成功？","仅记录人工对账结论，不会重新发送请求。","确认对账",()=>writeAction(`write:reconcile:${id}`,`/api/x-write/operations/${id}/reconcile`,{outcome,note},"对账已记录"));return;}
const accountActions={"verify-account":"verify","enable-account":"enable","disable-account":"disable","pause-account":"pause","resume-account":"resume"};if(accountActions[action]){const path=accountActions[action];if(action==="verify-account"){await writeAction(`write:${path}:${id}`,`/api/x-write/accounts/${id}/${path}`,{},"身份验证完成");return;}confirmDialog(`${{enable:"启用",disable:"停用",pause:"暂停",resume:"恢复"}[path]}该写入账号？`,"仅影响官方 API 写入服务，不影响浏览功能。","确认",()=>writeAction(`write:${path}:${id}`,`/api/x-write/accounts/${id}/${path}`,{},"账号状态已更新"));return;}}
const workflowState={candidates:[],loading:false,unavailable:""};
async function loadWorkflow(silent=false){if(workflowState.loading||state.view!=="workflow")return;workflowState.loading=true;try{const c=await api("/api/x/workflow/candidates?limit=50");workflowState.candidates=list(c.candidates);workflowState.unavailable="";api("/api/x/workflow/sync").catch(()=>{});}catch(e){workflowState.unavailable=e.message;if(!silent)toast("工作流同步失败",e.message,"error");}finally{workflowState.loading=false;renderWorkflow();}}
function workflowTone(s){return{succeeded:"ok",sent:"ok",draft_ready:"info",drafting:"warn",skipped:"warn",failed:"bad"}[s]||"warn";}
async function workflowPost(item,action,body={},success){const key=`wf:${action}:${item.item_key}`;if(state.pending.has(key))return;state.pending.add(key);try{const result=await api(`/api/x/workflow/items/${encodeURIComponent(item.item_key)}/${action}`,{method:"POST",body:JSON.stringify(body||{})});if(success)toast(success,"","success");await loadWorkflow(true);return result;}catch(e){toast("工作流操作失败",e.message,"error");return null;}finally{state.pending.delete(key);}}
function handleWorkflowAction(el){const key=el.dataset.wfItem,action=el.dataset.wfAction,item=workflowState.candidates.find(c=>c.item_key===key);if(!item)return;if(action==="draft"){workflowPost(item,"draft",{},"草稿已生成，请在下方确认后发出");return;}if(action==="regenerate"){workflowPost(item,"regenerate",{},"已重新生成草稿");return;}if(action==="skip"){confirmDialog("跳过这条帖子？","本次不处理，但保留记录；之后不再出现在候选列表。","确认跳过",()=>workflowPost(item,"skip",{},"已跳过"));return;}if(action==="copy"){const text=item.draft_text||"";if(!text){toast("该条还没有草稿","请先生成草稿","error");return;}copyText(text).then(()=>toast("评论已复制","去 X 上手动回复吧","success")).catch(()=>toast("复制失败","请手动选中评论复制","error"));return;}if(action==="approve"){if(!item.write_request_id){toast("该条还没有草稿","请先生成草稿","error");return;}confirmDialog("同意并发送这条评论？",`回复 @${item.author_handle} 的帖子：\n${item.draft_text||""}`,"确认发送",async()=>{try{const req=await api(`/api/x-write/requests/${item.write_request_id}`);const r=req.data||req;await api(`/api/x-write/requests/${item.write_request_id}/submit`,{method:"POST",body:"{}"});await api(`/api/x-write/requests/${item.write_request_id}/approve`,{method:"POST",body:JSON.stringify({content_hash:r.content_hash,request_version:r.version})});toast("评论已发出","将在写入操作中显示结果","success");await loadWorkflow(true);}catch(e){toast("发送失败",e.message,"error");}});return;}}
function renderWorkflow(){const el=$("#workflowList");if(state.view!=="workflow")return;if(workflowState.unavailable){el.innerHTML=`<div class="page-alert">工作流不可用：${esc(workflowState.unavailable)}</div>`;return;}const items=workflowState.candidates;$("#workflowCount").textContent=`${items.length} 条候选`;el.innerHTML=items.length?items.map(i=>{const m=i.metrics||{},metrics=[m.like_count?`赞 ${m.like_count}`:"",m.repost_count?`转发 ${m.repost_count}`:"",m.reply_count?`回复 ${m.reply_count}`:""].filter(Boolean).join(" · ");const text=i.text?(i.text.length>180?i.text.slice(0,180)+"…":i.text):"(无正文)";const hasDraft=i.status==="draft_ready"&&i.draft_text;return`<div class="write-row"><div class="write-row-main"><strong>@${esc(i.author_handle||"")} · ${esc(i.persona_label||i.expected_handle||"")} · ${esc((i.source||"").replace("search:","关键词："))}</strong><small><a href="${esc(i.url||"#")}" target="_blank" rel="noopener noreferrer">原帖</a> · ${esc(time(i.observed_at))}${metrics?` · ${esc(metrics)}`:""}</small><p class="workflow-text">${esc(text)}</p>${hasDraft?`<div class="preview-box"><strong>评论草稿</strong><p>${esc(i.draft_text)}</p>${i.note?`<small>理由：${esc(i.note)}</small>`:""}</div>`:""}${i.status==="skipped"?`<small>已跳过：${esc(i.note||"")}</small>`:""}</div><div class="write-row-side"><span class="badge ${workflowTone(i.status)}">${esc(i.status==="candidate"?"待起草":i.status==="draft_ready"?"草稿就绪":i.status==="drafting"?"生成中":i.status==="skipped"?"已跳过":i.status)}</span><div class="action-row">${hasDraft?`<button class="button primary" data-wf-action="copy" data-wf-item="${esc(i.item_key)}" type="button">复制评论</button><button class="button secondary" data-wf-action="approve" data-wf-item="${esc(i.item_key)}" type="button">同意并发送</button><button class="button secondary" data-wf-action="regenerate" data-wf-item="${esc(i.item_key)}" type="button">重新生成</button>`:i.status==="candidate"?`<button class="button primary" data-wf-action="draft" data-wf-item="${esc(i.item_key)}" type="button">生成评论草稿</button>`:""}<button class="button secondary" data-wf-action="skip" data-wf-item="${esc(i.item_key)}" type="button">跳过</button></div></div></div>`;}).join(""):`<div class="empty-state">暂无候选帖子。浏览 Worker 按关键词搜帖后会出现在这里；已发送或已跳过的不重复显示。</div>`;}
const postflowState={topics:[],accounts:[],accountId:"",loading:false,unavailable:""};
async function loadPostflow(silent=false){if(postflowState.loading||state.view!=="postflow")return;postflowState.loading=true;try{const ov=await api("/api/x/accounts");const accs=ov.accounts||[];postflowState.accounts=accs;if(!postflowState.accountId&&accs.length)postflowState.accountId=String(accs[0].id);const sel=$("#postflowAccount");if(sel){sel.innerHTML=accs.map(a=>`<option value="${a.id}" ${String(a.id)===postflowState.accountId?"selected":""}>${esc(a.persona_label||a.serial_number||`账号 ${a.id}`)}</option>`).join("");}if(postflowState.accountId){const t=await api(`/api/x/postflow/topics?account_id=${encodeURIComponent(postflowState.accountId)}&limit=100`);postflowState.topics=list(t.topics);postflowState.unavailable="";api("/api/x/postflow/sync").catch(()=>{});}else{postflowState.topics=[];}}catch(e){postflowState.unavailable=e.message;if(!silent)toast("选题加载失败",e.message,"error");}finally{postflowState.loading=false;renderPostflow();}}
function postflowTone(s){return{sent:"ok",draft_ready:"info",drafting:"warn",skipped:"warn",failed:"bad",consumed:"ok",selected:"info",candidate:"warn"}[s]||"warn";}
async function postflowPost(topic,action,body={},success){const key=`pf:${action}:${topic.topic_key}`;if(state.pending.has(key))return;state.pending.add(key);try{const result=await api(`/api/x/postflow/topics/${encodeURIComponent(topic.topic_key)}/${action}`,{method:"POST",body:JSON.stringify(body||{})});if(success)toast(success,"","success");await loadPostflow(true);return result;}catch(e){toast("操作失败",e.message,"error");return null;}finally{state.pending.delete(key);}}
function copyText(t){if(navigator.clipboard&&window.isSecureContext){return navigator.clipboard.writeText(t);}const ta=document.createElement("textarea");ta.value=t;ta.className="copy-scratch";document.body.appendChild(ta);ta.focus();ta.select();try{document.execCommand("copy");}catch(e){}document.body.removeChild(ta);return Promise.resolve();}
function handlePostflowAction(el){const key=el.dataset.pfTopic,action=el.dataset.pfAction,topic=postflowState.topics.find(t=>t.topic_key===key);if(!topic)return;const lang=String($("#postflowLang")?.value||"en");if(action==="generate"){postflowPost(topic,"generate",{language:lang},"正文已生成");return;}if(action==="regenerate"){postflowPost(topic,"regenerate",{language:lang},"已重新生成正文");return;}if(action==="skip"){confirmDialog("跳过这个选题？","本次不处理，但保留记录。","确认跳过",()=>postflowPost(topic,"skip",{},"已跳过"));return;}if(action==="copy"){const d=topic.drafts&&topic.drafts.find(x=>x.draft_key===el.dataset.pfDraft);const text=d&&d.post_text;if(!text){toast("没有正文","请先生成正文","error");return;}copyText(text).then(()=>toast("正文已复制","去 X 上手动发帖吧","success")).catch(()=>toast("复制失败","请手动选中正文复制","error"));return;}if(action==="manual_sent"){const d=topic.drafts&&topic.drafts.find(x=>x.draft_key===el.dataset.pfDraft);if(!d){toast("没有草稿","请先生成正文","error");return;}const html=`<div class="settings-form"><label class="full"><span>帖子链接（可选，发完后贴入，便于追溯）</span><input id="pfManualUrl" placeholder="https://x.com/.../status/..."></label></div>`;confirmDialog("确认已在 X 上手动发布？",html,"确认已发布",()=>postflowPost(topic,"manual_sent",{draft_key:d.draft_key,post_url:String($("#pfManualUrl")?.value||"").trim()},"已标记发布，飞书记录已写入"),"将记录到飞书「发帖记录」表，正文为草稿当前内容。");return;}if(action==="image"){postflowImageUpload(topic,el.dataset.pfDraft);return;}if(action==="submit"){postflowSubmit(topic,el.dataset.pfDraft);return;}}
function postflowImageUpload(topic,draftKey){const input=document.createElement("input");input.type="file";input.accept="image/*";input.onchange=async()=>{const file=input.files&&input.files[0];if(!file)return;if(file.size>5*1024*1024){toast("图片过大","请上传 5MB 以内的图片","error");return;}const reader=new FileReader();reader.onload=async()=>{const b64=String(reader.result||"").split(",")[1]||"";if(!b64){toast("读取失败","无法读取图片","error");return;}const res=await postflowPost(topic,"image",{bytes_base64:b64,mime_type:file.type,draft_key:draftKey||""},"图片已上传，发布时附到帖子");if(res&&res.media_asset_id){await loadPostflow(true);}};reader.readAsDataURL(file);};input.click();}
function postflowSubmit(topic,draftKey){const draft=topic.drafts&&topic.drafts.find(d=>d.draft_key===draftKey);if(!draft||!draft.post_text){toast("该选题还没有正文","请先生成正文","error");return;}const nowSec=Math.floor(Date.now()/1000);const defaultTime=new Date((nowSec+3600)*1000);const defaultLocal=new Date(defaultTime.getTime()-defaultTime.getTimezoneOffset()*60000).toISOString().slice(0,16);const promptText=`编辑发布内容（可修改正文）并选择发布时间。\n\n正文：\n${draft.post_text}`;const html=`<div class="settings-form"><label class="full"><span>帖子正文（最多 280 字）</span><textarea id="pfSubmitText" rows="4" maxlength="280">${esc(draft.post_text)}</textarea></label><label><span>发布时间（本地）</span><input type="datetime-local" id="pfSubmitTime" value="${defaultLocal}"></label>${draft.media_asset_id?`<small>已附图片（asset #${esc(draft.media_asset_id)}）</small>`:"<small>无配图（纯文本帖）</small>"}</div>`;confirmDialog("同意并定时发布",html,"确认提交审批",async()=>{const text=String($("#pfSubmitText")?.value||"").trim();const timeVal=String($("#pfSubmitTime")?.value||"");if(!text){toast("正文不能为空","","error");return;}if(!timeVal){toast("请选择发布时间","","error");return;}const scheduledAt=Math.floor(new Date(timeVal).getTime()/1000);if(scheduledAt<=nowSec){toast("发布时间必须在未来","","error");return;}if(scheduledAt>nowSec+86400*30){toast("发布时间不能超过 30 天后","","error");return;}await postflowPost(topic,"submit",{draft_key:draftKey,text:text,scheduled_at:scheduledAt},"已提交，等待审批发送");},"提交后进入写入服务的冻结审批；到点自动发布。");}
function renderPostflow(){const el=$("#postflowList");if(state.view!=="postflow")return;if(postflowState.unavailable){el.innerHTML=`<div class="page-alert">选题加载失败：${esc(postflowState.unavailable)}</div>`;return;}const topics=postflowState.topics;$("#postflowCount").textContent=`${topics.length} 个选题`;el.innerHTML=topics.length?topics.map(t=>{const kp=(t.key_points||[]).map(k=>`<li>${esc(k)}</li>`).join("");const ang=(t.angles||[]).map(a=>`<li>${esc(a)}</li>`).join("");const links=(t.suggested_links||[]).map(l=>`<li><a href="${esc(l)}" target="_blank" rel="noopener noreferrer">${esc(l)}</a></li>`).join("");const draft=t.drafts&&t.drafts[0];const hasDraft=draft&&(draft.post_text||draft.media_asset_id);const tone=postflowTone(t.status);const draftBox=hasDraft?`<div class="preview-box"><strong>帖子草稿</strong>${draft.post_text?`<p>${esc(draft.post_text)}</p>`:""}${draft.link?`<small>链接：${esc(draft.link)}</small>`:""}${draft.note?`<small>理由：${esc(draft.note)}</small>`:""}${draft.media_asset_id?`<small>已附图片 #${esc(draft.media_asset_id)}</small>`:""}</div>`:"";return`<div class="write-row"><div class="write-row-main"><strong>${esc(t.theme)}</strong>${t.keyword?` <small>关键词：${esc(t.keyword)}</small>`:""}${t.risk&&t.risk!=="无"?` <small class="badge bad">风险：${esc(t.risk)}</small>`:""}${kp?`<ul class="compact-list"><strong>主要观点</strong>${kp}</ul>`:""}${ang?`<ul class="compact-list"><strong>延展角度</strong>${ang}</ul>`:""}${links?`<ul class="compact-list"><strong>来源链接</strong>${links}</ul>`:""}${draftBox}${t.status==="skipped"?`<small>已跳过：${esc(t.note||"")}</small>`:""}</div><div class="write-row-side"><span class="badge ${tone}">${esc(t.status==="candidate"?"待生成":t.status==="selected"?"草稿中":t.status==="consumed"?"已提交":t.status==="skipped"?"已跳过":t.status)}</span><div class="action-row">${hasDraft?`<button class="button primary" data-pf-action="copy" data-pf-topic="${esc(t.topic_key)}" data-pf-draft="${esc(draft.draft_key)}" type="button">复制正文</button><button class="button secondary" data-pf-action="manual_sent" data-pf-topic="${esc(t.topic_key)}" data-pf-draft="${esc(draft.draft_key)}" type="button">标记已发布</button><button class="button secondary" data-pf-action="regenerate" data-pf-topic="${esc(t.topic_key)}" type="button">重新生成正文</button>`:`<button class="button primary" data-pf-action="generate" data-pf-topic="${esc(t.topic_key)}" type="button">生成正文</button>`}<button class="button secondary" data-pf-action="skip" data-pf-topic="${esc(t.topic_key)}" type="button">跳过</button></div></div></div>`;}).join(""):`<div class="empty-state">暂无选题。选好账号、关键词后点「归纳选题」，系统会把该账号近 30 天搜到的帖子归纳成可发帖的选题。</div>`;}
function bind(){
window.addEventListener("hashchange",()=>setView(location.hash.slice(1)));
document.addEventListener("toggle",e=>{const menu=e.target;if(menu.matches?.("details.duration-menu[data-disabled=\"true\"]")&&menu.open)menu.removeAttribute("open");},true);
$("#accountSearch").addEventListener("input",renderAccounts);$("#accountFilter").addEventListener("change",renderAccounts);$("#runFilters").addEventListener("click",e=>{const b=e.target.closest("[data-run-filter]");if(b){state.runFilter=b.dataset.runFilter;renderRuns();}});$("#runsAccountSelect")?.addEventListener("change",e=>{state.runsAccount=String(e.target.value||"");renderRuns();});
document.addEventListener("click",e=>{if(e.target.closest("[data-close-secret-dialog]")||e.target===$("#oauthAppDialog")||e.target===$("#oauth1Dialog")){closeSecretDialogs();return;}const waction=e.target.closest("[data-write-action]");if(waction){e.stopPropagation();handleWriteAction(waction);return;}const wfaction=e.target.closest("[data-wf-action]");if(wfaction){e.stopPropagation();handleWorkflowAction(wfaction);return;}const pfaction=e.target.closest("[data-pf-action]");if(pfaction){e.stopPropagation();handlePostflowAction(pfaction);return;}const action=e.target.closest("[data-action]");if(action){e.stopPropagation();handleAction(action);return;}const ar=e.target.closest("[data-account-id]");if(ar&&!e.target.closest("button,details,input,select,textarea,a"))openDrawer("account",ar.dataset.accountId,ar);const rr=e.target.closest("[data-run-id]");if(rr&&!e.target.closest("button,a"))openDrawer("run",rr.dataset.runId,rr);if(e.target.matches("[data-close-drawer]")||e.target===$("#drawerBackdrop"))closeDrawer();});
document.addEventListener("input",e=>{const f=e.target.closest("[data-write-field]");if(f){writeState.form[f.dataset.writeField]=f.value;return;}const connect=e.target.closest("[data-oauth-connect-field]");if(connect)writeState.connect[connect.dataset.oauthConnectField]=connect.value;});
document.addEventListener("change",e=>{const f=e.target.closest("select[data-write-field]");if(f){writeState.form[f.dataset.writeField]=f.value;renderWriteNew();return;}const connect=e.target.closest("select[data-oauth-connect-field]");if(connect){writeState.connect[connect.dataset.oauthConnectField]=connect.value;if(connect.dataset.oauthConnectField==="source_profile_id"){const profile=browseProfile(connect.value);writeState.connect.display_name=profile?.persona_label||profile?.serial_number||"";}if(connect.dataset.oauthConnectField==="account_id"&&connect.value){const account=writeState.accounts.find(a=>String(a.id)===String(connect.value));if(account)writeState.connect.display_name=account.display_name||writeState.connect.display_name;}renderWriteOAuth();}});
$("#oauthAppForm").addEventListener("submit",async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button[type="submit"]'),data=new FormData(form),clientId=String(data.get("client_id")||"").trim(),clientSecret=String(data.get("client_secret")||"");$("#oauthAppError").textContent="";if(!secureConsole()){$("#oauthAppError").textContent="必须通过 HTTPS 控制台提交。";form.reset();return;}if(!clientId){$("#oauthAppError").textContent="请填写 Client ID。";form.reset();return;}button.disabled=true;try{const payload={client_id:clientId,...(clientSecret?{client_secret:clientSecret}:{})};await api("/api/x-write/oauth/app",{method:"POST",body:JSON.stringify(payload)});toast("Developer App 已安全保存");closeSecretDialogs();await loadWrite(true);}catch(error){$("#oauthAppError").textContent=error.message;form.reset();}finally{button.disabled=false;}});
$("#oauth1Form").addEventListener("submit",async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button[type="submit"]'),data=new FormData(form),profile=browseProfile(String(data.get("source_profile_id")||""));$("#oauth1Error").textContent="";if(!secureConsole()){$("#oauth1Error").textContent="必须通过 HTTPS 控制台提交。";form.reset();return;}const payload={consumer_key:String(data.get("consumer_key")||""),consumer_secret:String(data.get("consumer_secret")||""),access_token:String(data.get("access_token")||""),access_token_secret:String(data.get("access_token_secret")||""),...(String(data.get("account_id")||"")?{account_id:number(data.get("account_id"))}:{}),...(profile?{source_profile_id:String(profile.profile_id),source_label:profileLabel(profile)}:{}),...(String(data.get("display_name")||"").trim()?{display_name:String(data.get("display_name")).trim()}:{})};if([payload.consumer_key,payload.consumer_secret,payload.access_token,payload.access_token_secret].some(v=>!v)){$("#oauth1Error").textContent="请完整填写四项 OAuth 1.0a 凭据。";form.reset();return;}button.disabled=true;try{await api("/api/x-write/credentials/oauth1",{method:"POST",body:JSON.stringify(payload)});toast("OAuth 1.0a 账号已验证并保存");closeSecretDialogs();await loadWrite(true);}catch(error){$("#oauth1Error").textContent=error.message;for(const field of ["consumer_key","consumer_secret","access_token","access_token_secret"])form.elements[field].value="";}finally{button.disabled=false;}});
$("#confirmCancel").addEventListener("click",closeConfirm);$("#confirmProceed").addEventListener("click",async()=>{const fn=state.confirmAction;closeConfirm();if(fn)await fn();});$("#confirmDialog").addEventListener("click",e=>{if(e.target===$("#confirmDialog"))closeConfirm();});
$("#globalScheduleButton").addEventListener("click",()=>{const paused=$("#globalScheduleButton").dataset.paused==="true";if(paused){const accounts=eligibleOnResume(),retries=retryEligible();confirmDialog("恢复全局排程？","恢复后，服务端会重新评估时间窗口、预算、重试冷却和 Worker 容量。","确认恢复",()=>submitAction("global:resume","/api/x/schedule/resume",{},"全局排程已恢复"),`当前最多有 ${accounts} 个账号和 ${retries} 条重试可能重新具备资格；实际是否入队以服务端判断为准。`);}else confirmDialog("暂停全局排程？","暂停后不再创建新的自动任务，当前运行不会被结束。","确认暂停",()=>submitAction("global:pause","/api/x/schedule/pause",{},"全局排程已暂停"),"这是安全的默认状态，不表示系统故障。");});
$("#postflowAccount")?.addEventListener("change",e=>{postflowState.accountId=String(e.target.value||"");loadPostflow(true);});
$("#postflowSummarizeBtn")?.addEventListener("click",async()=>{if(!postflowState.accountId){toast("请先选择账号","","error");return;}const btn=$("#postflowSummarizeBtn");btn.disabled=true;try{const keyword=String($("#postflowKeyword")?.value||"").trim();const instruction=String($("#postflowInstruction")?.value||"").trim();await api("/api/x/postflow/summarize",{method:"POST",body:JSON.stringify({account_id:number(postflowState.accountId),keyword,instruction})});toast("选题已归纳","在下方查看并生成正文","success");await loadPostflow(true);}catch(e){toast("归纳失败",e.message,"error");}finally{btn.disabled=false;}});
$("#logoutButton").addEventListener("click",()=>confirmDialog("退出登录？","退出后需要重新输入管理员密码。","确认退出",async()=>{try{await api("/logout",{method:"POST",body:"{}"});location.assign("/login");}catch(e){toast("退出失败",e.message,"error");}}));
document.addEventListener("keydown",e=>{containDrawerFocus(e);if(e.key==="Escape"){if(!$("#oauthAppDialog").classList.contains("hidden")||!$("#oauth1Dialog").classList.contains("hidden"))closeSecretDialogs();else if(!$("#confirmDialog").classList.contains("hidden"))closeConfirm();else if(state.drawer)closeDrawer();}});document.addEventListener("visibilitychange",()=>{if(!document.hidden)loadOverview(true);});}

bind();setView(location.hash.slice(1));loadOverview();setInterval(()=>{if(document.hidden)return;loadOverview(true);if(state.view==="write")loadWrite(true);if(state.view==="workflow")loadWorkflow(true);if(state.view==="postflow")loadPostflow(true);},4000);
